html:
{% set bill = doc %}
{% set bill_ef = efris_receipt_data(doc) if (efris_receipt_data is defined and doc.docstatus == 1) else none %}
<article>
<h1>{{ _("COPY") }} {% if doc.copy_number %}#{{ doc.copy_number }}{% endif %}</h1>
<p>{{ _("Original invoice") }}: {{ doc.name | e }}<br>{{ _("Reprinted") }}: {{ doc.copy_timestamp or frappe.utils.now() }}<br>{{ _("Posting date") }}: {{ doc.posting_date }}</p>
<table class="table table-condensed"><thead><tr><th>{{ _("Item") }}</th><th>{{ _("Qty") }}</th><th>{{ _("Amount") }} ({{ doc.currency | e }})</th></tr></thead><tbody>
{% for row in doc.get('items') %}<tr><td>{{ row.item_name | e }}</td><td>{{ row.qty }}</td><td>{{ row.amount }}</td></tr>{% endfor %}</tbody></table>
{% for tax in doc.taxes %}<p>{{ tax.description | striptags | e }}: {{ tax.tax_amount }}</p>{% endfor %}
<p>{{ _("Grand total") }}: {{ doc.grand_total }} {{ doc.currency | e }}<br>{{ _("Rounded total") }}: {{ doc.rounded_total }} {{ doc.currency | e }}</p>
{% for payment in doc.payments if payment.amount %}<p>{{ payment.mode_of_payment | e }}: {{ payment.amount }} {{ doc.currency | e }}</p>{% endfor %}
<p>{{ _("Outstanding") }}: {{ doc.outstanding_amount }} {{ doc.currency | e }}</p>{% if doc.outstanding_amount and doc.outstanding_amount > 0 %}<p>{{ _("Charged to account") }} {{ doc.customer | e }}: {{ doc.outstanding_amount }} {{ doc.currency | e }}</p>{% endif %}
{% if bill_ef %}
<div class="efris" style="margin-top: 10px;">
{% if bill_ef.state == "fiscalised" %}
<p class="text-center"><b>URA EFRIS</b></p>
<p>{{ _("FDN") }} : <b>{{ bill_ef.fdn | e }}</b>{% if bill_ef.verification_code %}<br>{{ _("Verification code") }} : <b>{{ bill_ef.verification_code | e }}</b>{% endif %}{% if bill_ef.device_no %}<br>{{ _("Device No") }} : {{ bill_ef.device_no | e }}{% endif %}{% if bill_ef.issued %}<br>{{ _("Issued") }} : {{ bill_ef.issued | e }}{% endif %}{% if bill_ef.is_return and bill_ef.original_fdn %}<br>{{ _("Original FDN") }} : {{ bill_ef.original_fdn | e }}{% endif %}{% if bill.tax_id %}<br>{{ _("Buyer TIN") }} : {{ bill.tax_id | e }}{% endif %}</p>
{% set einv = frappe.get_doc("E Invoice", bill.efris_e_invoice) if bill.efris_e_invoice else none %}
{% if einv and einv.taxes %}<table class="table table-condensed"><thead><tr><th>{{ _("Tax category") }}</th><th class="text-right">{{ _("Net") }}</th><th class="text-right">{{ _("Tax") }}</th></tr></thead><tbody>{% for t in einv.taxes %}<tr><td>{{ ((t.tax_category_code or "").split(":", 1) | last) | e }}</td><td class="text-right">{{ frappe.utils.fmt_money(t.net_amount, currency=bill.currency) }}</td><td class="text-right">{{ frappe.utils.fmt_money(t.tax_amount, currency=bill.currency) }}</td></tr>{% endfor %}</tbody></table>{% endif %}
{% if bill_ef.qr %}<p class="text-center"><img src="{{ bill_ef.qr | e }}" alt="EFRIS QR" style="width: 34mm; height: 34mm;"></p>{% endif %}
{% elif bill_ef.state == "credit_note_pending" %}
<p class="text-center"><b>{{ _("CREDIT NOTE PENDING URA APPROVAL") }}</b>{% if bill_ef.application_ref %}<br>{{ _("Application Ref") }} : {{ bill_ef.application_ref | e }}{% endif %}</p>
{% elif bill_ef.state == "pending" %}
<p class="text-center"><b>{{ _("FISCAL RECEIPT PENDING") }}</b><br>{{ _("Not a tax invoice until URA issues the FDN. Ask for a reprint.") }}</p>
{% else %}
<p class="text-center">{{ _("Not a fiscal receipt") }}</p>
{% endif %}
{% if bill_ef.sandbox %}<p class="text-center"><b>*** {{ _("EFRIS SANDBOX - NOT A VALID TAX INVOICE") }} ***</b></p>{% endif %}
</div>
{% endif %}</article>
